function findPeakElement(nums) {
  let low = 0;
  let high = nums.length - 1;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (nums[mid] > nums[mid + 1]) {
      high = mid;          // downhill: a peak is at mid or to its left
    } else {
      low = mid + 1;       // uphill: a peak is to the right
    }
  }
  return low;
}

